/**
 * The app's theme catalogue.
 *
 * `system`, `light` and `dark` are the built-ins whose tokens are authored directly in
 * `src/renderer/src/styles.css`. Every other theme is data: its palette lives here and the
 * matching CSS is generated by {@link themeCss}, so the renderer, the native window chrome
 * and the terminal's ANSI palette all read the same numbers.
 */

export type ThemeId =
  | 'system'
  | 'light'
  | 'dark'
  | 'midnight'
  | 'abyss'
  | 'blueprint'
  | 'admiral'
  | 'nebula'
  | 'solarium'
  | 'evergreen'
  | 'blossom'
  | 'graphite'
  | 'ember'
  | 'ultraviolet'
  | 'magma'
  | 'lagoon'
  | 'fjord'
  | 'claret'
  | 'citrine'
  | 'cappuccino'
  | 'meadow'
  | 'porcelain'
  | 'lavender';

export type ThemeGroup = 'core' | 'navy' | 'futuristic' | 'light' | 'dark';

/** Every color token a theme must define. Keys map to `--kebab-case` custom properties. */
export interface ThemePalette {
  bg: string;
  bgElev: string;
  bgSunken: string;
  bgHover: string;
  bgActive: string;
  fg: string;
  fgMuted: string;
  fgFaint: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentFg: string;
  green: string;
  amber: string;
  red: string;
  blue: string;
  purple: string;
  cyan: string;
  userBubble: string;
  shadow: string;
}

export interface ThemeDescriptor {
  id: ThemeId;
  name: string;
  group: ThemeGroup;
  /** Drives `nativeTheme.themeSource` and the light/dark branch of derived colors. */
  base: 'system' | 'light' | 'dark';
  description: string;
  /** True for themes that add motion; all of it is disabled under `prefers-reduced-motion`. */
  animated?: boolean;
  /** Absent for the three built-ins, whose tokens are authored in styles.css. */
  palette?: ThemePalette;
}

/** Caption colors for the frameless title bar: the theme's `--bg-elev` / `--fg`. */
export interface ThemeChrome {
  color: string;
  symbolColor: string;
}

/**
 * The built-ins' chrome colors. These mirror the `:root` / `[data-theme='dark']` blocks in
 * `src/renderer/src/styles.css`, which is where those two palettes are authored.
 */
const BUILTIN_CHROME: Record<'light' | 'dark', ThemeChrome> = {
  light: { color: '#ffffff', symbolColor: '#1c1c1f' },
  dark: { color: '#191c23', symbolColor: '#e6e7ea' }
};

