export const THEME_IDS: ThemeId[] = THEMES.map((t) => t.id);

export const GROUP_LABELS: Record<ThemeGroup, string> = {
  core: 'Core',
  navy: 'Navy',
  futuristic: 'Futuristic',
  light: 'Light',
  dark: 'Dark'
};

/** Menu/picker order: groups in this order, themes in catalogue order within each group. */
export const GROUP_ORDER: ThemeGroup[] = ['core', 'navy', 'futuristic', 'light', 'dark'];

export function isThemeId(v: unknown): v is ThemeId {
  return typeof v === 'string' && THEME_IDS.includes(v as ThemeId);
}

export function findTheme(id: string): ThemeDescriptor | undefined {
  return THEMES.find((t) => t.id === id);
}

/** The `nativeTheme.themeSource` value a theme needs so OS-drawn surfaces match it. */
export function themeSourceFor(id: string): 'system' | 'light' | 'dark' {
  return findTheme(id)?.base ?? 'system';
}

/**
 * Whether a theme paints a dark UI. `system` has no answer of its own, so callers pass what
 * the OS currently reports.
 */
export function isDarkTheme(id: string, systemDark: boolean): boolean {
  const base = themeSourceFor(id);
  return base === 'system' ? systemDark : base === 'dark';
}

export function chromeFor(id: string, systemDark: boolean): ThemeChrome {
  const t = findTheme(id);
  if (t?.palette) return { color: t.palette.bgElev, symbolColor: t.palette.fg };
  return BUILTIN_CHROME[isDarkTheme(id, systemDark) ? 'dark' : 'light'];
}

/** Three representative colors for a theme swatch, in paint order (base, raised, accent). */
export function swatchFor(id: string, systemDark: boolean): [string, string, string] {
  const p = findTheme(id)?.palette;
  if (p) return [p.bgSunken, p.bgElev, p.accent];
  const dark = isDarkTheme(id, systemDark);
  return dark ? ['#0d0f13', '#191c23', '#8b8bff'] : ['#efeff1', '#ffffff', '#5b5bd6'];
}

function cssName(key: string): string {
  return `--${key.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`)}`;
}

/**
 * Categorical series colours for the analytics charts (`--chart-1` … `--chart-6`), one set per
 * light/dark base rather than per theme: the theme hues are UI accents, and several of them (the
 * desaturated Graphite and Ember sets, the bright dark-theme badges) fail the colour-vision and
 * lightness checks a data palette must pass. This order clears every adjacent-pair check on all
 * catalogue surfaces; the first three slots also pass all-pairs. Light surfaces put slots 3–5 below
 * 3:1 contrast, so every chart ships a legend, hover values and a table view.
 */
export const CHART_SERIES: Record<'light' | 'dark', string[]> = {
  light: ['#2a78d6', '#eb6834', '#1baf7a', '#eda100', '#e87ba4', '#008300'],
  dark: ['#3987e5', '#d95926', '#199e70', '#c98500', '#d55181', '#008300']
};

export function chartSeriesCss(base: 'light' | 'dark'): string[] {
  return CHART_SERIES[base].map((hex, i) => `  --chart-${i + 1}: ${hex};`);
}

/**
 * CSS for every data-driven theme.
 *
 * The selectors are prefixed with `html` so they outrank `:root:not([data-theme='light'])` in
 * `styles.css` regardless of which stylesheet the browser sees first.
 */
export function themeCss(): string {
  const blocks: string[] = [];
  for (const t of THEMES) {
    if (!t.palette) continue;
    const base = t.base === 'light' ? 'light' : 'dark';
    const decls = Object.entries(t.palette).map(([k, v]) => `  ${cssName(k)}: ${v};`);
    decls.unshift(`  color-scheme: ${base};`);
    decls.push(...chartSeriesCss(base));
    blocks.push(`html:root[data-theme='${t.id}'] {\n${decls.join('\n')}\n}`);
  }
  return blocks.join('\n');
}
